function Home() {
  return (
    <div className="home-page">
      <div className="home-section">
        <div className="home-card">
          <h1>MediReminder</h1>
          <p>
            A smart medicine reminder web application to help you track
            medicines, dosage, timing, and daily reminders.
          </p>
        </div>
      </div>
    </div>
  );
}

export default Home;
